const fs=require('fs'),p=require('path');const root=p.resolve(__dirname,'..'),src=p.join(root,'reconstituit/jadx/app/src/main/java'),out=p.join(root,'protocol-comunicare');fs.mkdirSync(out,{recursive:true});const ob='com/alipay/verifyiotidentity/obfuscated/';
const read=f=>fs.readFileSync(p.join(src,f),'utf8');const cache={};
function constants(file){if(cache[file])return cache[file];const s=read(file),o={};cache[file]=o;for(const m of s.matchAll(/(?:public|private|protected) static final (String|int|byte|long) (\w+) = ([^;]+);/g)){let x=m[3];if(/^"[\s\S]*"$/.test(x)){try{x=JSON.parse(x)}catch{}}else if(/^-?\d+[Ll]?$/.test(x))x=Number(x.replace(/[Ll]$/,''));o[m[2]]=x;}return o;}
function resolve(expr,file,depth=0){expr=expr.trim();if(depth>5)return {expression:expr};if(/^"[\s\S]*"$/.test(expr)){try{return JSON.parse(expr)}catch{return expr}}if(/^-?\d+[Ll]?$/.test(expr))return Number(expr.replace(/[Ll]$/,''));const m=expr.match(/^(\w+)\.(\w+)$/);if(m){const content=read(file);const imp=content.match(new RegExp('import ([\\w.]+\\.'+m[1]+');'));const f=imp?imp[1].replaceAll('.','/')+'.java':ob+m[1]+'.java';if(fs.existsSync(p.join(src,f))){const val=constants(f)[m[2]];if(val!==undefined)return val;}}return {expression:expr};}
function methods(file){const s=read(file),a=[...s.matchAll(/^    (?:public|private|protected)[^\r\n]*\([^\r\n]*\)(?: throws [^{]+)? \{/gm)];return a.map((m,i)=>({signature:m[0].trim(),line:s.slice(0,m.index).split('\n').length,body:s.slice(m.index,a[i+1]?.index??s.length)}));}
const commands=[];for(const file of [ob+'zb0.java',ob+'zka.java'])for(const m of methods(file)){const opts=[...m.body.matchAll(/\b\w+\.put\("opt", (?:Integer\.valueOf\(([^)]+)\)|([^;]+?))\);/g)];if(!opts.length)continue;const fields=[...m.body.matchAll(/\b\w+\.put\(("[^"\r\n]+"|[\w.]+), ([^\r\n]+)\);/g)].map(a=>({key:resolve(a[1],file),valueExpression:a[2]}));commands.push({transport:file.endsWith('zka.java')?'wifi':'ble',source:file,line:m.line,method:m.signature,opt:opts.map(a=>resolve(a[1]||a[2],file)),fields,mergedMaps:[...m.body.matchAll(/\.putAll\(([^;]+)\);/g)].map(a=>a[1])});}
const schemas=[];const dirs=['com/iflytek/fanyi/blc/service/bean','com/iflytek/easytrans/headset/bluetooth/bean','translate_sdk'];for(const dir of dirs)for(const f of fs.readdirSync(p.join(src,dir)).filter(f=>f.endsWith('.java'))){const file=dir+'/'+f,s=read(file);const fields=[...s.matchAll(/@SerializedName\(([^\n]+)\)\s+(?:public|private|protected) ([\w<>?, .\[\]]+) (\w+)(?:\s*=([^;]+))?;/g)].map(m=>({wireName:resolve(m[1],file),javaType:m[2],javaField:m[3],line:s.slice(0,m.index).split('\n').length}));const mapKeys=[...new Set([...s.matchAll(/(?:\.put\(|ut9\.a\()((?:"[^"\r\n]+"|[\w.]+)),/g)].map(m=>JSON.stringify(resolve(m[1],file))))].map(JSON.parse);if(fields.length||mapKeys.length)schemas.push({source:file,fields,mapKeys});}
const defs={ble:constants(ob+'aa4.java'),wifi:constants('com/example/recorde_translate_plugin/glass/wifip2p/wifi/protocol/IBluetoothProtocol.java')};for(const [f,data] of Object.entries({'commands.json':commands,'schemas.json':schemas,'constants.json':defs}))fs.writeFileSync(p.join(out,f),JSON.stringify(data,null,2));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const val=x=>typeof x==='object'?JSON.stringify(x):String(x);
let body='<h1>Catalog API și pachete extrase</h1><p><a href="INDEX.html">Specificația explicată</a> · <a href="commands.json">Comenzi JSON</a> · <a href="schemas.json">Scheme JSON</a> · <a href="constants.json">Constante</a></p><p>Extracție statică. Numele simbolurilor sunt obfuscate; expresiile nesoluționate sunt păstrate. Semantica unui cod numeric depinde de transport, profil și model. Nu sunt incluse valori de sesiune sau credențiale funcționale.</p><h2>Constructori de comenzi</h2><table><tr><th>Transport / opt</th><th>Metodă și sursă</th><th>Câmpuri</th><th>Hărți adăugate</th></tr>';
for(const c of commands)body+='<tr><td>'+esc(c.transport+' '+c.opt.map(val).join(', '))+'</td><td><a href="../reconstituit/jadx/app/src/main/java/'+c.source+'">'+esc(c.method)+'</a><br>linia '+c.line+'</td><td>'+c.fields.map(f=>esc(val(f.key)+' = '+f.valueExpression)).join('<br>')+'</td><td>'+esc(c.mergedMaps.join(', '))+'</td></tr>';body+='</table><h2>Scheme de obiecte</h2>';
for(const s of schemas)body+='<details><summary>'+esc(s.source)+'</summary><pre>'+esc(JSON.stringify(s,null,2))+'</pre><a href="../reconstituit/jadx/app/src/main/java/'+s.source+'">Sursă Java</a></details>';
fs.writeFileSync(p.join(out,'CATALOG.html'),'<!doctype html><html lang="ro"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catalog protocol APK</title><style>body{font:15px/1.5 system-ui;margin:30px;color:#183148}table{border-collapse:collapse;width:100%}td,th{padding:10px;border:1px solid #ccd7e3;text-align:left;vertical-align:top}td,pre{overflow-wrap:anywhere;white-space:pre-wrap}summary{padding:12px;cursor:pointer}</style>'+body+'</html>');
console.log(JSON.stringify({constructors:commands.length,ble:commands.filter(x=>x.transport==='ble').length,wifi:commands.filter(x=>x.transport==='wifi').length,schemas:schemas.length}));
